contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount < 10 ether);
        uint recorded = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        assert(recorded == 0);
    }
    receive() external payable {}
}

